type UpdateRouteRecoveryHistogramParams struct {
	ObservedSeconds float64
	UpdatedAt       pgtype.Timestamptz
}

func (q *Queries) UpdateRouteRecoveryHistogram(ctx context.Context, arg UpdateRouteRecoveryHistogramParams) (ControlRouteRecoveryHistogram, error) {
	row := q.db.QueryRow(ctx, updateRouteRecoveryHistogram, arg.ObservedSeconds, arg.UpdatedAt)
	var i ControlRouteRecoveryHistogram
	err := row.Scan(
		&i.Singleton,
		&i.ObservationCount,
		&i.ObservationSumSeconds,
		&i.BucketLe025,
		&i.BucketLe05,
		&i.BucketLe1,
		&i.BucketLe2,
		&i.BucketLe5,
		&i.BucketLe10,
		&i.BucketLe20,
		&i.BucketLe30,
		&i.BucketLe45,
		&i.BucketLe60,
		&i.BucketLe120,
		&i.UpdatedAt,
	)
	return i, err
}
